        folder = os.path.join(root, label)
        if label.startswith("_") or not os.path.isdir(folder):
            continue
        out += [os.path.join(folder, f) for f in sorted(os.listdir(folder)) if f.endswith(".npz")]
    return out


def count_blocks(root=DATA_DIR):
