}

bool readRaw(int16_t* v) {  // ax ay az temp gx gy gz
  Wire.beginTransmission(mpuAddr);
  Wire.write(REG_ACCEL_XOUT_H);
  if (Wire.endTransmission(false) != 0 || Wire.requestFrom(mpuAddr, (uint8_t)14) != 14) {
    return false;
  }
