        v[i] = (int16_t)((raw[2 * i] << 8) | raw[2 * i + 1]);
      }
      if (good == 0) {
        memcpy(first, v, sizeof(v));
      }
      for (int i = 0; i < 7; i++) {
        sum[i] += v[i];
        sq[i] += (double)v[i] * v[i];
        changed[i] |= v[i] != first[i];
      }
      good++;
    } else {
      failed++;
    }
